function countryTreasures(key){if(key!=='mexico')return '';return '<section class="mexico-treasures" aria-label="Mexico treasures"><p class="treasures-label treasure-reward-line"><span>TREASURES OF MEXICO — Collect all 3. Earn your profile sombrero.</span><svg class="sombrero-outline" viewBox="0 0 100 78" role="img" aria-label="Golden sombrero profile reward"><defs><linearGradient id="reward-gold" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff0b6"/><stop offset=".4" stop-color="#d9a643"/><stop offset=".7" stop-color="#f6d77d"/><stop offset="1" stop-color="#a66d24"/></linearGradient><linearGradient id="reward-crown"><stop stop-color="#b77b2e"/><stop offset=".5" stop-color="#ffe8a0"/><stop offset="1" stop-color="#be8431"/></linearGradient></defs><ellipse cx="50" cy="61" rx="43" ry="11" fill="#67451b" opacity=".15"/><path d="M7 49Q6 39 28 42L72 42Q94 38 94 49Q91 65 50 67Q10 65 7 49Z" fill="url(#reward-gold)" stroke="#87602b" stroke-width="1.5"/><path d="M28 44Q32 34 35 22Q40 6 50 9Q61 7 66 23L73 44Q52 57 28 44Z" fill="url(#reward-crown)" stroke="#87602b" stroke-width="1.5"/><path d="M31 36Q50 47 70 36L73 44Q51 57 28 44Z" fill="#8c4c31" stroke="#70452b"/><path d="M34 41l5 4 5-1 5 4 5-2 5 1 5-5 5-1" fill="none" stroke="#f8d783" stroke-width="2"/><path d="M11 49Q50 72 90 48M15 54Q50 73 86 54" fill="none" stroke="#fff0b0" stroke-width="1.4"/><path d="M39 22Q43 12 48 13" fill="none" stroke="#fff1be" stroke-width="2" stroke-linecap="round"/><path d="M14 19v10m-5-5h10M83 17v8m-4-4h8" stroke="#c2984c" stroke-width="1.3" stroke-linecap="round"/></svg></p><div class="treasure-badges">'+mexicoTreasureData.map((t,i)=>'<button type="button" class="treasure-badge" data-treasure="'+i+'" aria-label="Discover '+t.name+'" aria-pressed="false">'+mexicoTreasureIcons[i]+'<span class="treasure-caption"><strong>'+t.name+'</strong><span>'+t.subtitle+'</span></span></button>').join('')+'</div><div class="treasure-inline-details" hidden role="region" aria-label="Selected treasure details" aria-live="polite"></div></section>';}

function clearTreasureDetails(){const panel=document.querySelector('.treasure-inline-details');if(panel){panel.hidden=true;panel.replaceChildren();}document.querySelectorAll('[data-treasure]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});}
function setupTreasureDetails(){document.querySelectorAll('[data-treasure]').forEach(button=>button.onclick=()=>{
 document.querySelectorAll('[data-treasure]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});
 const t=mexicoTreasureData[Number(button.dataset.treasure)],panel=document.querySelector('.treasure-inline-details');
 panel.innerHTML='<h3>'+t.name+'</h3><p>'+t.description+'</p><p class="treasure-region">'+t.region+'</p><a class="treasure-map-link" href="https://www.google.com/maps/search/?api=1&amp;query='+t.lat+','+t.lon+'" target="_blank" rel="noopener noreferrer">Latitude '+t.lat.toFixed(4)+'° · Longitude '+t.lon.toFixed(4)+'° ↗ Google Maps</a>';panel.hidden=false;
});}
document.addEventListener('click',event=>{if(event.target.closest('[data-treasure]'))return;const link=event.target.closest('.treasure-map-link');if(link){setTimeout(clearTreasureDetails,0);return;}clearTreasureDetails();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')clearTreasureDetails();});
